  z-index: 1;
}
.play-btn svg { width: 20px; height: 20px; color: var(--teal); margin-left: 2px; }
.video-card-body { padding: 14px 16px; background: var(--white); border: 1px solid var(--gray-200); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
.video-card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--white);
  padding: 56px 0 32px;
}
.footer-newsletter {
  max-width: 560px;
  margin: 0 auto 40px;
  text-align: center;
}
.footer-newsletter p {
  font-size: 15px;
  opacity: 0.8;
  line-height: 1.6;
  margin-bottom: 20px;
}
.footer-newsletter-form {
  display: flex;
  gap: 10px;
}
.footer-newsletter-form input {
  flex: 1;
  padding: 12px 18px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 24px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.footer-newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.footer-newsletter-form input:focus { border-color: var(--teal); }
.footer-newsletter-form button {
  background: var(--teal);
  color: var(--white);
  padding: 12px 28px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.footer-newsletter-form button:hover { background: var(--teal-dark); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
  padding: 28px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--white); }
.footer-legal {
  text-align: center;
  padding-top: 28px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
  line-height: 1.6;
  max-width: 700px;
  margin: 0 auto;
}
.footer-social {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 24px;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}
.footer-social a:hover { background: var(--teal); }
.footer-social svg { width: 16px; height: 16px; fill: var(--white); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .programs-grid { grid-template-columns: repeat(2, 1fr); }
  .videos-grid { grid-template-columns: repeat(2, 1fr); }
  .reads-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .hero-title { font-size: 30px; }
  .nav-list { overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
  .nav-list::-webkit-scrollbar { display: none; }
  .mega-menu { min-width: 300px; left: 0; right: 0; }
  .mega-menu-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .section-header h2 { font-size: 22px; }
  .trust-grid { grid-template-columns: 1fr; }
  .programs-grid { grid-template-columns: 1fr; }
  .videos-grid { grid-template-columns: 1fr 1fr; }
  .reads-grid { grid-template-columns: 1fr; }
  .footer-newsletter-form { flex-direction: column; }
  .header-actions .sign-in { display: none; }
}
@media (max-width: 480px) {
  .hero-title { font-size: 26px; }
  .container { padding: 0 16px; }
  .videos-grid { grid-template-columns: 1fr; }
}
