tool_use_result.content:
/* ===== WellSource — Global Styles ===== */

:root {
  --teal: #02838D;
  --teal-dark: #026a73;
  --teal-light: #e6f5f6;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8725A;
  --coral-dark: #d4604a;
  --amber: #F59E0B;
  --amber-light: #FEF3C7;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-size: 26px;
  font-weight: 800;
  color: var(--teal);
  letter-spacing: -0.5px;
}
.logo span { color: var(--charcoal); }
.header-actions { display: flex; align-items: center; gap: 16px; }
.header-actions a {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  transition: color 0.2s;
}
.header-actions a:hover { color: var(--teal); }
.btn-subscribe {
  background: var(--teal);
  color: var(--white) !important;
  padding: 8px 20px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-subscribe:hover { background: var(--teal-dark); }

/* Main Nav */
.main-nav { border-top: 1px solid var(--gray-100); }
.nav-list {
  display: flex;
  align-items: center;
  gap: 0;
}
.nav-item { position: relative; }
.nav-item > button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  font-size: 15px;
  font-weight: 600;
  color: var(--charcoal);
  transition: color 0.2s, background 0.2s;
  border-radius: 0;
}
.nav-item > button:hover,
.nav-item.active > button {
  color: var(--teal);
  background: var(--teal-light);
}
.nav-item > button svg {
  width: 12px;
  height: 12px;
  transition: transform 0.2s;
}
.nav-item.active > button svg { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 520px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 24px 28px;
  z-index: 999;
}
.nav-item.active .mega-menu { display: block; }
.mega-menu-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 12px;
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 32px;
}
.mega-menu-grid a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 0;
  transition: color 0.15s;
  white-space: nowrap;
}
.mega-menu-grid a:hover { color: var(--teal); }
.mega-menu-section + .mega-menu-section { margin-top: 20px; border-top: 1px solid var(--gray-100); padding-top: 16px; }

/* ===== CREDIBILITY TICKER ===== */
.credibility-ticker {
  background: var(--charcoal);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
}
.ticker-track {
  display: inline-flex;
  animation: ticker-scroll 30s linear infinite;
}
.ticker-track:hover { animation-play-state: paused; }
.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 40px;
  font-size: 14px;
  font-weight: 500;
}
.ticker-item svg { width: 16px; height: 16px; flex-shrink: 0; fill: var(--teal); color: var(--teal); }
.ticker-dot {
  width: 4px;
  height: 4px;
  background: var(--gray-500);
  border-radius: 50%;
  flex-shrink: 0;
}
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== HERO ===== */
.hero {
  padding: 48px 0;
  background: linear-gradient(135deg, var(--teal-light) 0%, var(--white) 100%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 40px;
  align-items: start;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--amber-light);
  color: var(--amber);
  font-size: 13px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 24px;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.hero-category {
  display: inline-block;
  font-size: 13px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}
.hero-title {
  font-size: 40px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--charcoal);
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 18px;
  color: var(--gray-600);
  line-height: 1.6;
  max-width: 560px;
}
.hero-image-placeholder {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 100%);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.3);
  font-size: 80px;
}

/* Trending Sidebar */
.trending-sidebar { margin-top: 8px; }
.trending-sidebar h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--charcoal);
}
.trending-list { display: flex; flex-direction: column; gap: 0; }
.trending-item {
  display: flex;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
  transition: background 0.15s;
  cursor: pointer;
}
.trending-item:last-child { border-bottom: none; }
.trending-item:hover .trending-item-title { color: var(--teal); }
.trending-number {
  font-size: 28px;
  font-weight: 800;
  color: var(--gray-200);
  line-height: 1;
  min-width: 36px;
}
.trending-item-cat {
  font-size: 12px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.trending-item-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
  transition: color 0.15s;
}

/* ===== NEWSLETTER CTA ===== */
.newsletter-cta {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 50%, var(--teal-dark) 100%);
  padding: 60px 0;
  text-align: center;
  color: var(--white);
}
.newsletter-cta h2 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
}
.newsletter-cta p {
  font-size: 17px;
  opacity: 0.9;
  max-width: 500px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 28px;
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
.newsletter-form input:focus {
  border-color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.2);
}
.newsletter-form button {
  background: var(--coral);
  color: var(--white);
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--coral-dark); }
.newsletter-form button:active { transform: scale(0.97); }
.newsletter-privacy {
  font-size: 13px;
  opacity: 0.7;
  margin-top: 14px;
}

/* ===== SECTION HEADERS ===== */
.section { padding: 56px 0; }
.section-alt { background: var(--gray-50); }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
}
.section-header h2 {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
}
.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 16px; height: 16px; }

/* ===== HEALTH TOPICS CAROUSEL ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding: 8px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.topic-card {
  flex: 0 0 160px;
  text-align: center;
  cursor: pointer;
  transition: transform 0.2s;
}
.topic-card:hover { transform: translateY(-4px); }
.topic-card-img {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  box-shadow: var(--shadow-md);
  transition: box-shadow 0.2s;
}
.topic-card:hover .topic-card-img { box-shadow: var(--shadow-lg); }
.topic-card-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: background 0.2s, box-shadow 0.2s;
}
.carousel-btn:hover { background: var(--gray-50); box-shadow: var(--shadow-lg); }
.carousel-btn svg { width: 18px; height: 18px; color: var(--charcoal); }
.carousel-btn-left { left: -16px; }
.carousel-btn-right { right: -16px; }

/* ===== HEALTH TOOLS ===== */
.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}
.tool-feature-card {
  background: linear-gradient(135deg, var(--teal-light) 0%, #e0f2f3 100%);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid rgba(2,131,141,0.1);
}
.tool-feature-card h3 {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 12px;
  color: var(--charcoal);
}
.tool-feature-card p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 20px;
}
.btn-teal {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--teal);
  color: var(--white);
  padding: 12px 24px;
  border-radius: 28px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-teal:hover { background: var(--teal-dark); }
.tool-mini-cards { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
.tool-mini-card {
  background: var(--white);
  border-radius: var(--radius-sm);
  padding: 16px;
  display: flex;
  align-items: start;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s;
  cursor: pointer;
}
.tool-mini-card:hover { box-shadow: var(--shadow-md); }
.tool-mini-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 18px;
}
.tool-mini-card h4 {
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}
.tool-mini-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}
.tools-right { display: flex; flex-direction: column; gap: 16px; }
.tool-list-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  align-items: start;
  gap: 16px;
  transition: box-shadow 0.2s, border-color 0.2s;
  cursor: pointer;
}
.tool-list-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--teal);
}
.tool-list-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 22px;
}
.tool-list-card h4 {
  font-size: 16px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 4px;
}
.tool-list-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.5;
}
.tool-list-cta {
  font-size: 13px;
  font-weight: 600;
  color: var(--teal);
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ===== RECOMMENDED READS ===== */
.tab-bar {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--gray-100);
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-500);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color 0.2s, border-color 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--charcoal); }
.tab-btn.active {
  color: var(--teal);
  border-bottom-color: var(--teal);
}
.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.read-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.15s;
  cursor: pointer;
}
.read-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.read-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}
.read-card-body { padding: 20px; }
.read-card-cat {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--teal);
  margin-bottom: 8px;
}
.read-card-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ===== TRUST PILLARS ===== */
.trust-section {
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
  padding: 64px 0;
  text-align: center;
}
.trust-section h2 {
  font-size: 30px;
  font-weight: 800;
  margin-bottom: 48px;
  color: var(--charcoal);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.trust-card {
  text-align: center;
  padding: 24px;
}
.trust-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 28px;
}
.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--charcoal);
}
.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FEATURED PROGRAMS ===== */
.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.program-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.program-card-img {
  height: 200px;
  display: flex;
  align-items: flex-end;
  padding: 20px;
}
.program-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0) 60%);
}
.program-card-title {
  position: relative;
  z-index: 1;
  font-size: 15px;
  font-weight: 700;
  color: var(--white);
  line-height: 1.3;
}

/* ===== LATEST VIDEOS ===== */
.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.video-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.video-thumb {
  position: relative;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-btn {
  position: absolute;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(255,255,255,0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  z-index: 1;
}
.play-btn svg { width: 20px; height: 20px; color: var(--teal); margin-left: 2px; }
.video-card-body { padding: 14px 16px; background: var(--white); border: 1px solid var(--gray-200); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
.video-card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--white);
  padding: 56px 0 32px;
}
.footer-newsletter {
  max-width: 560px;
  margin: 0 auto 40px;
  text-align: center;
}
.footer-newsletter p {
  font-size: 15px;
  opacity: 0.8;
  line-height: 1.6;
  margin-bottom: 20px;
}
.footer-newsletter-form {
  display: flex;
  gap: 10px;
}
.footer-newsletter-form input {
  flex: 1;
  padding: 12px 18px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 24px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.footer-newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.footer-newsletter-form input:focus { border-color: var(--teal); }
.footer-newsletter-form button {
  background: var(--teal);
  color: var(--white);
  padding: 12px 28px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.footer-newsletter-form button:hover { background: var(--teal-dark); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
  padding: 28px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--white); }
.footer-legal {
  text-align: center;
  padding-top: 28px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
  line-height: 1.6;
  max-width: 700px;
  margin: 0 auto;
}
.footer-social {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 24px;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}
.footer-social a:hover { background: var(--teal); }
.footer-social svg { width: 16px; height: 16px; fill: var(--white); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .programs-grid { grid-template-columns: repeat(2, 1fr); }
  .videos-grid { grid-template-columns: repeat(2, 1fr); }
  .reads-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .hero-title { font-size: 30px; }
  .nav-list { overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
  .nav-list::-webkit-scrollbar { display: none; }
  .mega-menu { min-width: 300px; left: 0; right: 0; }
  .mega-menu-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .section-header h2 { font-size: 22px; }
  .trust-grid { grid-template-columns: 1fr; }
  .programs-grid { grid-template-columns: 1fr; }
  .videos-grid { grid-template-columns: 1fr 1fr; }
  .reads-grid { grid-template-columns: 1fr; }
  .footer-newsletter-form { flex-direction: column; }
  .header-actions .sign-in { display: none; }
}
@media (max-width: 480px) {
  .hero-title { font-size: 26px; }
  .container { padding: 0 16px; }
  .videos-grid { grid-template-columns: 1fr; }
}

/* ===== WellSource — Global Styles ===== */

:root {
  --teal: #02838D;
  --teal-dark: #026a73;
  --teal-light: #e6f5f6;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8725A;
  --coral-dark: #d4604a;
  --amber: #F59E0B;
  --amber-light: #FEF3C7;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-size: 26px;
  font-weight: 800;
  color: var(--teal);
  letter-spacing: -0.5px;
}
.logo span { color: var(--charcoal); }
.header-actions { display: flex; align-items: center; gap: 16px; }
.header-actions a {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  transition: color 0.2s;
}
.header-actions a:hover { color: var(--teal); }
.btn-subscribe {
  background: var(--teal);
  color: var(--white) !important;
  padding: 8px 20px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-subscribe:hover { background: var(--teal-dark); }

/* Main Nav */
.main-nav { border-top: 1px solid var(--gray-100); }
.nav-list {
  display: flex;
  align-items: center;
  gap: 0;
}
.nav-item { position: relative; }
.nav-item > button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  font-size: 15px;
  font-weight: 600;
  color: var(--charcoal);
  transition: color 0.2s, background 0.2s;
  border-radius: 0;
}
.nav-item > button:hover,
.nav-item.active > button {
  color: var(--teal);
  background: var(--teal-light);
}
.nav-item > button svg {
  width: 12px;
  height: 12px;
  transition: transform 0.2s;
}
.nav-item.active > button svg { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 520px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 24px 28px;
  z-index: 999;
}
.nav-item.active .mega-menu { display: block; }
.mega-menu-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 12px;
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 32px;
}
.mega-menu-grid a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 0;
  transition: color 0.15s;
  white-space: nowrap;
}
.mega-menu-grid a:hover { color: var(--teal); }
.mega-menu-section + .mega-menu-section { margin-top: 20px; border-top: 1px solid var(--gray-100); padding-top: 16px; }

/* ===== CREDIBILITY TICKER ===== */
.credibility-ticker {
  background: var(--charcoal);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
}
.ticker-track {
  display: inline-flex;
  animation: ticker-scroll 30s linear infinite;
}
.ticker-track:hover { animation-play-state: paused; }
.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 40px;
  font-size: 14px;
  font-weight: 500;
}
.ticker-item svg { width: 16px; height: 16px; flex-shrink: 0; fill: var(--teal); color: var(--teal); }
.ticker-dot {
  width: 4px;
  height: 4px;
  background: var(--gray-500);
  border-radius: 50%;
  flex-shrink: 0;
}
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== HERO ===== */
.hero {
  padding: 48px 0;
  background: linear-gradient(135deg, var(--teal-light) 0%, var(--white) 100%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 40px;
  align-items: start;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--amber-light);
  color: var(--amber);
  font-size: 13px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 24px;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.hero-category {
  display: inline-block;
  font-size: 13px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}
.hero-title {
  font-size: 40px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--charcoal);
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 18px;
  color: var(--gray-600);
  line-height: 1.6;
  max-width: 560px;
}
.hero-image-placeholder {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 100%);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.3);
  font-size: 80px;
}

/* Trending Sidebar */
.trending-sidebar { margin-top: 8px; }
.trending-sidebar h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--charcoal);
}
.trending-list { display: flex; flex-direction: column; gap: 0; }
.trending-item {
  display: flex;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
  transition: background 0.15s;
  cursor: pointer;
}
.trending-item:last-child { border-bottom: none; }
.trending-item:hover .trending-item-title { color: var(--teal); }
.trending-number {
  font-size: 28px;
  font-weight: 800;
  color: var(--gray-200);
  line-height: 1;
  min-width: 36px;
}
.trending-item-cat {
  font-size: 12px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.trending-item-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
  transition: color 0.15s;
}

/* ===== NEWSLETTER CTA ===== */
.newsletter-cta {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 50%, var(--teal-dark) 100%);
  padding: 60px 0;
  text-align: center;
  color: var(--white);
}
.newsletter-cta h2 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
}
.newsletter-cta p {
  font-size: 17px;
  opacity: 0.9;
  max-width: 500px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 28px;
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
.newsletter-form input:focus {
  border-color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.2);
}
.newsletter-form button {
  background: var(--coral);
  color: var(--white);
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--coral-dark); }
.newsletter-form button:active { transform: scale(0.97); }
.newsletter-privacy {
  font-size: 13px;
  opacity: 0.7;
  margin-top: 14px;
}

/* ===== SECTION HEADERS ===== */
.section { padding: 56px 0; }
.section-alt { background: var(--gray-50); }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
}
.section-header h2 {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
}
.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 16px; height: 16px; }

/* ===== HEALTH TOPICS CAROUSEL ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding: 8px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.topic-card {
  flex: 0 0 160px;
  text-align: center;
  cursor: pointer;
  transition: transform 0.2s;
}
.topic-card:hover { transform: translateY(-4px); }
.topic-card-img {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  box-shadow: var(--shadow-md);
  transition: box-shadow 0.2s;
}
.topic-card:hover .topic-card-img { box-shadow: var(--shadow-lg); }
.topic-card-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: background 0.2s, box-shadow 0.2s;
}
.carousel-btn:hover { background: var(--gray-50); box-shadow: var(--shadow-lg); }
.carousel-btn svg { width: 18px; height: 18px; color: var(--charcoal); }
.carousel-btn-left { left: -16px; }
.carousel-btn-right { right: -16px; }

/* ===== HEALTH TOOLS ===== */
.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}
.tool-feature-card {
  background: linear-gradient(135deg, var(--teal-light) 0%, #e0f2f3 100%);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid rgba(2,131,141,0.1);
}
.tool-feature-card h3 {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 12px;
  color: var(--charcoal);
}
.tool-feature-card p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 20px;
}
.btn-teal {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--teal);
  color: var(--white);
  padding: 12px 24px;
  border-radius: 28px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-teal:hover { background: var(--teal-dark); }
.tool-mini-cards { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
.tool-mini-card {
  background: var(--white);
  border-radius: var(--radius-sm);
  padding: 16px;
  display: flex;
  align-items: start;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s;
  cursor: pointer;
}
.tool-mini-card:hover { box-shadow: var(--shadow-md); }
.tool-mini-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 18px;
}
.tool-mini-card h4 {
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}
.tool-mini-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}
.tools-right { display: flex; flex-direction: column; gap: 16px; }
.tool-list-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  align-items: start;
  gap: 16px;
  transition: box-shadow 0.2s, border-color 0.2s;
  cursor: pointer;
}
.tool-list-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--teal);
}
.tool-list-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 22px;
}
.tool-list-card h4 {
  font-size: 16px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 4px;
}
.tool-list-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.5;
}
.tool-list-cta {
  font-size: 13px;
  font-weight: 600;
  color: var(--teal);
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ===== RECOMMENDED READS ===== */
.tab-bar {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--gray-100);
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-500);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color 0.2s, border-color 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--charcoal); }
.tab-btn.active {
  color: var(--teal);
  border-bottom-color: var(--teal);
}
.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.read-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.15s;
  cursor: pointer;
}
.read-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.read-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}
.read-card-body { padding: 20px; }
.read-card-cat {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--teal);
  margin-bottom: 8px;
}
.read-card-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ===== TRUST PILLARS ===== */
.trust-section {
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
  padding: 64px 0;
  text-align: center;
}
.trust-section h2 {
  font-size: 30px;
  font-weight: 800;
  margin-bottom: 48px;
  color: var(--charcoal);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.trust-card {
  text-align: center;
  padding: 24px;
}
.trust-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 28px;
}
.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--charcoal);
}
.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FEATURED PROGRAMS ===== */
.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.program-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.program-card-img {
  height: 200px;
  display: flex;
  align-items: flex-end;
  padding: 20px;
}
.program-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0) 60%);
}
.program-card-title {
  position: relative;
  z-index: 1;
  font-size: 15px;
  font-weight: 700;
  color: var(--white);
  line-height: 1.3;
}

/* ===== LATEST VIDEOS ===== */
.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.video-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.video-thumb {
  position: relative;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-btn {
  position: absolute;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(255,255,255,0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  z-index: 1;
}
.play-btn svg { width: 20px; height: 20px; color: var(--teal); margin-left: 2px; }
.video-card-body { padding: 14px 16px; background: var(--white); border: 1px solid var(--gray-200); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
.video-card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--white);
  padding: 56px 0 32px;
}
.footer-newsletter {
  max-width: 560px;
  margin: 0 auto 40px;
  text-align: center;
}
.footer-newsletter p {
  font-size: 15px;
  opacity: 0.8;
  line-height: 1.6;
  margin-bottom: 20px;
}
.footer-newsletter-form {
  display: flex;
  gap: 10px;
}
.footer-newsletter-form input {
  flex: 1;
  padding: 12px 18px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 24px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.footer-newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.footer-newsletter-form input:focus { border-color: var(--teal); }
.footer-newsletter-form button {
  background: var(--teal);
  color: var(--white);
  padding: 12px 28px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.footer-newsletter-form button:hover { background: var(--teal-dark); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
  padding: 28px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--white); }
.footer-legal {
  text-align: center;
  padding-top: 28px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
  line-height: 1.6;
  max-width: 700px;
  margin: 0 auto;
}
.footer-social {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 24px;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}
.footer-social a:hover { background: var(--teal); }
.footer-social svg { width: 16px; height: 16px; fill: var(--white); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .programs-grid { grid-template-columns: repeat(2, 1fr); }
  .videos-grid { grid-template-columns: repeat(2, 1fr); }
  .reads-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .hero-title { font-size: 30px; }
  .nav-list { overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
  .nav-list::-webkit-scrollbar { display: none; }
  .mega-menu { min-width: 300px; left: 0; right: 0; }
  .mega-menu-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .section-header h2 { font-size: 22px; }
  .trust-grid { grid-template-columns: 1fr; }
  .programs-grid { grid-template-columns: 1fr; }
  .videos-grid { grid-template-columns: 1fr 1fr; }
  .reads-grid { grid-template-columns: 1fr; }
  .footer-newsletter-form { flex-direction: column; }
  .header-actions .sign-in { display: none; }
}
@media (max-width: 480px) {
  .hero-title { font-size: 26px; }
  .container { padding: 0 16px; }
  .videos-grid { grid-template-columns: 1fr; }
}

raw_arguments.content:
/* ===== WellSource — Global Styles ===== */

:root {
  --teal: #02838D;
  --teal-dark: #026a73;
  --teal-light: #e6f5f6;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8725A;
  --coral-dark: #d4604a;
  --amber: #F59E0B;
  --amber-light: #FEF3C7;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
}
.logo {
  font-size: 26px;
  font-weight: 800;
  color: var(--teal);
  letter-spacing: -0.5px;
}
.logo span { color: var(--charcoal); }
.header-actions { display: flex; align-items: center; gap: 16px; }
.header-actions a {
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  transition: color 0.2s;
}
.header-actions a:hover { color: var(--teal); }
.btn-subscribe {
  background: var(--teal);
  color: var(--white) !important;
  padding: 8px 20px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-subscribe:hover { background: var(--teal-dark); }

/* Main Nav */
.main-nav { border-top: 1px solid var(--gray-100); }
.nav-list {
  display: flex;
  align-items: center;
  gap: 0;
}
.nav-item { position: relative; }
.nav-item > button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  font-size: 15px;
  font-weight: 600;
  color: var(--charcoal);
  transition: color 0.2s, background 0.2s;
  border-radius: 0;
}
.nav-item > button:hover,
.nav-item.active > button {
  color: var(--teal);
  background: var(--teal-light);
}
.nav-item > button svg {
  width: 12px;
  height: 12px;
  transition: transform 0.2s;
}
.nav-item.active > button svg { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 520px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 24px 28px;
  z-index: 999;
}
.nav-item.active .mega-menu { display: block; }
.mega-menu-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 12px;
}
.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 32px;
}
.mega-menu-grid a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 0;
  transition: color 0.15s;
  white-space: nowrap;
}
.mega-menu-grid a:hover { color: var(--teal); }
.mega-menu-section + .mega-menu-section { margin-top: 20px; border-top: 1px solid var(--gray-100); padding-top: 16px; }

/* ===== CREDIBILITY TICKER ===== */
.credibility-ticker {
  background: var(--charcoal);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
}
.ticker-track {
  display: inline-flex;
  animation: ticker-scroll 30s linear infinite;
}
.ticker-track:hover { animation-play-state: paused; }
.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 40px;
  font-size: 14px;
  font-weight: 500;
}
.ticker-item svg { width: 16px; height: 16px; flex-shrink: 0; fill: var(--teal); color: var(--teal); }
.ticker-dot {
  width: 4px;
  height: 4px;
  background: var(--gray-500);
  border-radius: 50%;
  flex-shrink: 0;
}
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== HERO ===== */
.hero {
  padding: 48px 0;
  background: linear-gradient(135deg, var(--teal-light) 0%, var(--white) 100%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 40px;
  align-items: start;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--amber-light);
  color: var(--amber);
  font-size: 13px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 24px;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.hero-category {
  display: inline-block;
  font-size: 13px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}
.hero-title {
  font-size: 40px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--charcoal);
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}
.hero-subtitle {
  font-size: 18px;
  color: var(--gray-600);
  line-height: 1.6;
  max-width: 560px;
}
.hero-image-placeholder {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 100%);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.3);
  font-size: 80px;
}

/* Trending Sidebar */
.trending-sidebar { margin-top: 8px; }
.trending-sidebar h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--charcoal);
}
.trending-list { display: flex; flex-direction: column; gap: 0; }
.trending-item {
  display: flex;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
  transition: background 0.15s;
  cursor: pointer;
}
.trending-item:last-child { border-bottom: none; }
.trending-item:hover .trending-item-title { color: var(--teal); }
.trending-number {
  font-size: 28px;
  font-weight: 800;
  color: var(--gray-200);
  line-height: 1;
  min-width: 36px;
}
.trending-item-cat {
  font-size: 12px;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.trending-item-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--charcoal);
  transition: color 0.15s;
}

/* ===== NEWSLETTER CTA ===== */
.newsletter-cta {
  background: linear-gradient(135deg, var(--teal) 0%, #04a5b2 50%, var(--teal-dark) 100%);
  padding: 60px 0;
  text-align: center;
  color: var(--white);
}
.newsletter-cta h2 {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
}
.newsletter-cta p {
  font-size: 17px;
  opacity: 0.9;
  max-width: 500px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 28px;
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
.newsletter-form input:focus {
  border-color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.2);
}
.newsletter-form button {
  background: var(--coral);
  color: var(--white);
  padding: 14px 32px;
  border-radius: 28px;
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--coral-dark); }
.newsletter-form button:active { transform: scale(0.97); }
.newsletter-privacy {
  font-size: 13px;
  opacity: 0.7;
  margin-top: 14px;
}

/* ===== SECTION HEADERS ===== */
.section { padding: 56px 0; }
.section-alt { background: var(--gray-50); }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
}
.section-header h2 {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
}
.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}
.view-all:hover { gap: 8px; }
.view-all svg { width: 16px; height: 16px; }

/* ===== HEALTH TOPICS CAROUSEL ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding: 8px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.topic-card {
  flex: 0 0 160px;
  text-align: center;
  cursor: pointer;
  transition: transform 0.2s;
}
.topic-card:hover { transform: translateY(-4px); }
.topic-card-img {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  box-shadow: var(--shadow-md);
  transition: box-shadow 0.2s;
}
.topic-card:hover .topic-card-img { box-shadow: var(--shadow-lg); }
.topic-card-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: background 0.2s, box-shadow 0.2s;
}
.carousel-btn:hover { background: var(--gray-50); box-shadow: var(--shadow-lg); }
.carousel-btn svg { width: 18px; height: 18px; color: var(--charcoal); }
.carousel-btn-left { left: -16px; }
.carousel-btn-right { right: -16px; }

/* ===== HEALTH TOOLS ===== */
.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}
.tool-feature-card {
  background: linear-gradient(135deg, var(--teal-light) 0%, #e0f2f3 100%);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid rgba(2,131,141,0.1);
}
.tool-feature-card h3 {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 12px;
  color: var(--charcoal);
}
.tool-feature-card p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 20px;
}
.btn-teal {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--teal);
  color: var(--white);
  padding: 12px 24px;
  border-radius: 28px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-teal:hover { background: var(--teal-dark); }
.tool-mini-cards { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
.tool-mini-card {
  background: var(--white);
  border-radius: var(--radius-sm);
  padding: 16px;
  display: flex;
  align-items: start;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s;
  cursor: pointer;
}
.tool-mini-card:hover { box-shadow: var(--shadow-md); }
.tool-mini-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 18px;
}
.tool-mini-card h4 {
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}
.tool-mini-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}
.tools-right { display: flex; flex-direction: column; gap: 16px; }
.tool-list-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  align-items: start;
  gap: 16px;
  transition: box-shadow 0.2s, border-color 0.2s;
  cursor: pointer;
}
.tool-list-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--teal);
}
.tool-list-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 22px;
}
.tool-list-card h4 {
  font-size: 16px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 4px;
}
.tool-list-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.5;
}
.tool-list-cta {
  font-size: 13px;
  font-weight: 600;
  color: var(--teal);
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ===== RECOMMENDED READS ===== */
.tab-bar {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  border-bottom: 2px solid var(--gray-100);
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.tab-bar::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-500);
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color 0.2s, border-color 0.2s;
  white-space: nowrap;
}
.tab-btn:hover { color: var(--charcoal); }
.tab-btn.active {
  color: var(--teal);
  border-bottom-color: var(--teal);
}
.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.read-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow 0.2s, transform 0.15s;
  cursor: pointer;
}
.read-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.read-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}
.read-card-body { padding: 20px; }
.read-card-cat {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--teal);
  margin-bottom: 8px;
}
.read-card-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ===== TRUST PILLARS ===== */
.trust-section {
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
  padding: 64px 0;
  text-align: center;
}
.trust-section h2 {
  font-size: 30px;
  font-weight: 800;
  margin-bottom: 48px;
  color: var(--charcoal);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.trust-card {
  text-align: center;
  padding: 24px;
}
.trust-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 28px;
}
.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--charcoal);
}
.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== FEATURED PROGRAMS ===== */
.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.program-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.program-card-img {
  height: 200px;
  display: flex;
  align-items: flex-end;
  padding: 20px;
}
.program-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0) 60%);
}
.program-card-title {
  position: relative;
  z-index: 1;
  font-size: 15px;
  font-weight: 700;
  color: var(--white);
  line-height: 1.3;
}

/* ===== LATEST VIDEOS ===== */
.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
}
.video-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.video-thumb {
  position: relative;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-btn {
  position: absolute;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(255,255,255,0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  z-index: 1;
}
.play-btn svg { width: 20px; height: 20px; color: var(--teal); margin-left: 2px; }
.video-card-body { padding: 14px 16px; background: var(--white); border: 1px solid var(--gray-200); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
.video-card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--white);
  padding: 56px 0 32px;
}
.footer-newsletter {
  max-width: 560px;
  margin: 0 auto 40px;
  text-align: center;
}
.footer-newsletter p {
  font-size: 15px;
  opacity: 0.8;
  line-height: 1.6;
  margin-bottom: 20px;
}
.footer-newsletter-form {
  display: flex;
  gap: 10px;
}
.footer-newsletter-form input {
  flex: 1;
  padding: 12px 18px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 24px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.footer-newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.footer-newsletter-form input:focus { border-color: var(--teal); }
.footer-newsletter-form button {
  background: var(--teal);
  color: var(--white);
  padding: 12px 28px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}
.footer-newsletter-form button:hover { background: var(--teal-dark); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 24px;
  padding: 28px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--white); }
.footer-legal {
  text-align: center;
  padding-top: 28px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
  line-height: 1.6;
  max-width: 700px;
  margin: 0 auto;
}
.footer-social {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 24px;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
}
.footer-social a:hover { background: var(--teal); }
.footer-social svg { width: 16px; height: 16px; fill: var(--white); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .programs-grid { grid-template-columns: repeat(2, 1fr); }
  .videos-grid { grid-template-columns: repeat(2, 1fr); }
  .reads-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .hero-title { font-size: 30px; }
  .nav-list { overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
  .nav-list::-webkit-scrollbar { display: none; }
  .mega-menu { min-width: 300px; left: 0; right: 0; }
  .mega-menu-grid { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
  .section-header h2 { font-size: 22px; }
  .trust-grid { grid-template-columns: 1fr; }
  .programs-grid { grid-template-columns: 1fr; }
  .videos-grid { grid-template-columns: 1fr 1fr; }
  .reads-grid { grid-template-columns: 1fr; }
  .footer-newsletter-form { flex-direction: column; }
  .header-actions .sign-in { display: none; }
}
@media (max-width: 480px) {
  .hero-title { font-size: 26px; }
  .container { padding: 0 16px; }
  .videos-grid { grid-template-columns: 1fr; }
}
